// Web: src/index.js mounts <App> with createRoot inside a HashRouter with one route "*".
// Mobile: Expo Router does this. app/_layout.tsx is the root and the todo-list screen is the route "/".
// Nothing else to port; screens can read the app routes from here.
export const APP_ROUTES = ["/"] as const

import { useState } from "react"
import { FlatList, Pressable, StyleSheet, Text, TextInput, View } from "react-native"

type Todo = { id: number; title: string; completed: boolean }

export default function TodoList() {
  const [todos, setTodos] = useState<Todo[]>([])
  const [title, setTitle] = useState("")
  const left = todos.filter((t) => !t.completed).length

  function add() {
    if (title.trim() === "") return
    setTodos([...todos, { id: Date.now(), title: title.trim(), completed: false }])
    setTitle("")
  }

  return (
    <View style={styles.page}>
      <div className="header">
        <Text role="heading" style={styles.title}>todos</Text>
      </div>
      <TextInput
        placeholder="What needs to be done?"
        value={title}
        onChangeText={setTitle}
        onSubmitEditing={add}
        style={styles.input}
      />
      <FlatList
        role="list"
        data={todos}
        keyExtractor={(t) => String(t.id)}
        renderItem={({ item }) => (
          <View role="listitem" style={styles.row}>
            <Pressable
              role="checkbox"
              aria-checked={item.completed}
              onPress={() => setTodos(todos.map((t) => (t.id === item.id ? { ...t, completed: !t.completed } : t)))}
            >
              <Text>{item.completed ? "☑" : "☐"}</Text>
            </Pressable>
            <Text style={styles.grow}>{item.title}</Text>
            <Pressable role="button" accessibilityLabel="Delete todo" onPress={() => setTodos(todos.filter((t) => t.id !== item.id))}>
              <Text>×</Text>
            </Pressable>
          </View>
        )}
      />
      {todos.length > 0 && (
        <View style={styles.row}>
          <Text style={styles.grow}>{left} {left === 1 ? "item" : "items"} left!</Text>
          <Pressable role="button" onPress={() => setTodos(todos.filter((t) => !t.completed))}>
            <Text>Clear completed</Text>
          </Pressable>
        </View>
      )}
    </View>
  )
}

const styles = StyleSheet.create({
  page: { flex: 1, padding: 16, gap: 12 },
  title: { fontSize: 48, textAlign: "center" },
  input: { borderWidth: 1, borderColor: "#ccc", padding: 12, fontSize: 18 },
  row: { flexDirection: "row", alignItems: "center", gap: 12, paddingVertical: 8 },
  grow: { flex: 1 },
})

